-- WoW Forever: items that drop from creatures on the live realm and are missing from that creature's loot here (and from
-- Everlake's open data). Only drops seen at least 3 times in at least 5 loot windows.
-- Data from Efficient Games (https://efficient.games), licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/).
-- Source: github.com/JIVESCORP/eg-link-output-wowf loot datasets (players' loot windows), builds 70205-70959.
-- Changed: picked and converted; chance = drops / loot windows (ESTIMATED from small samples, group 0). Items that are a quest objective
-- drop only for players on that quest (QuestRequired 1).
-- A creature with no loot table gets one under its own entry. Safe to run again.

UPDATE `creature_template_difficulty` SET `LootID`=`Entry` WHERE `DifficultyID`=0 AND `LootID`=0 AND `Entry` IN (255774,256383,257926,258797,262473,266850);
